mapper.select:
SELECT * FROM oauth2_consent
WHERE registered_client_id = #{registeredClientId}
  AND principal_name = #{principalName}

mapper.delete:
DELETE FROM oauth2_consent
WHERE registered_client_id = #{registeredClientId}
  AND principal_name = #{principalName}

mapper.insert:
INSERT INTO oauth2_consent (
    registered_client_id, principal_name, authorities
) VALUES (
             #{registeredClientId}, #{principalName}, #{authorities}
         )

mapper.update:
UPDATE oauth2_consent
SET
    authorities = #{authorities}
WHERE
    registered_client_id = #{registeredClientId}
  AND principal_name = #{principalName}
